     3→use jsonwebtoken::{Algorithm, EncodingKey, Header, encode, get_current_timestamp};
     4→use rand::Rng;
     5→use serde::{Deserialize, Serialize};
     6→use zeroize::Zeroize;
     7→
     8→/// Default algorithm used for JWT token signing.
     9→const DEFAULT_ALGORITHM: Algorithm = Algorithm::HS256;
    10→
    11→/// JWT secret length in bytes.
    12→pub const JWT_SECRET_LENGTH: usize = 32;
    13→
    14→#[derive(Debug)]
    15→pub enum Error {
    16→    JWT(jsonwebtoken::errors::Error),
    17→    InvalidToken,
    18→    InvalidKey(String),
    19→}
    20→
    21→impl From<jsonwebtoken::errors::Error> for Error {
    22→    fn from(e: jsonwebtoken::errors::Error) -> Self {
    23→        Error::JWT(e)
    24→    }
    25→}
    26→
    27→/// Provides wrapper around `[u8; JWT_SECRET_LENGTH]` that implements `Zeroize`.
    28→#[derive(Zeroize, Clone)]
    29→#[zeroize(drop)]
    30→pub struct JwtKey([u8; JWT_SECRET_LENGTH]);
    31→
    32→impl JwtKey {
    33→    /// Wrap given slice in `Self`. Returns an error if slice.len() != `JWT_SECRET_LENGTH`.
    34→    pub fn from_slice(key: &[u8]) -> Result<Self, String> {
    35→        if key.len() != JWT_SECRET_LENGTH {
    36→            return Err(format!(
    37→                "Invalid key length. Expected {} got {}",
    38→                JWT_SECRET_LENGTH,
    39→                key.len()
    40→            ));
    41→        }
    42→        let mut res = [0; JWT_SECRET_LENGTH];
    43→        res.copy_from_slice(key);
    44→        Ok(Self(res))
    45→    }
    46→
    47→    /// Generate a random secret.
    48→    pub fn random() -> Self {
    49→        Self(rand::rng().random::<[u8; JWT_SECRET_LENGTH]>())
    50→    }
    51→
    52→    /// Returns a reference to the underlying byte array.
    53→    pub fn as_bytes(&self) -> &[u8] {
    54→        &self.0
    55→    }
    56→
    57→    /// Returns the hex encoded `String` for the secret.
    58→    pub fn hex_string(&self) -> String {
    59→        hex::encode(self.0)
    60→    }
    61→}
    62→
    63→pub fn strip_prefix(s: &str) -> &str {
    64→    if let Some(stripped) = s.strip_prefix("0x") {
    65→        stripped
    66→    } else {
    67→        s
    68→    }
    69→}
    70→
    71→/// Contains the JWT secret and claims parameters.
    72→pub struct Auth {
    73→    key: EncodingKey,
    74→    id: Option<String>,
    75→    clv: Option<String>,
    76→}
    77→
    78→impl Auth {
    79→    pub fn new(secret: JwtKey, id: Option<String>, clv: Option<String>) -> Self {
    80→        Self {
    81→            key: EncodingKey::from_secret(secret.as_bytes()),
    82→            id,
    83→            clv,
    84→        }
    85→    }
    86→
    87→    /// Create a new `Auth` struct given the path to the file containing the hex
    88→    /// encoded jwt key.
    89→    pub fn new_with_path(
    90→        jwt_path: PathBuf,
    91→        id: Option<String>,
    92→        clv: Option<String>,
    93→    ) -> Result<Self, Error> {
    94→        std::fs::read_to_string(&jwt_path)
    95→            .map_err(|e| {
    96→                Error::InvalidKey(format!(
    97→                    "Failed to read JWT secret file {:?}, error: {:?}",
    98→                    jwt_path, e
    99→                ))
   100→            })
   101→            .and_then(|ref s| {
   102→                let secret_bytes = hex::decode(strip_prefix(s.trim_end()))
   103→                    .map_err(|e| Error::InvalidKey(format!("Invalid hex string: {:?}", e)))?;
   104→                let secret = JwtKey::from_slice(&secret_bytes).map_err(Error::InvalidKey)?;
   105→                Ok(Self::new(secret, id, clv))
   106→            })
   107→    }
   108→
   109→    /// Generate a JWT token with `claims.iat` set to current time.
   110→    pub fn generate_token(&self) -> Result<String, Error> {
   111→        let claims = self.generate_claims_at_timestamp();
   112→        self.generate_token_with_claims(&claims)
   113→    }
   114→
   115→    /// Generate a JWT token with the given claims.
   116→    fn generate_token_with_claims(&self, claims: &Claims) -> Result<String, Error> {
   117→        let header = Header::new(DEFAULT_ALGORITHM);
   118→        Ok(encode(&header, claims, &self.key)?)
   119→    }
   120→
